def require(ok, msg):
    if not ok:
        raise RuntimeError(msg)

def replace_once(s, old, new):
    require(s.count(old)==1, "Ancre inattendue : "+old[:100])
    return s.replace(old,new,1)

def build(folder):
    for name, encoded in PAYLOAD.items():
        raw=base64.b64decode(encoded,validate=True)
        blob=hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()
        require(blob==GIT_BLOBS[name],"Integrite du module incorrecte : "+name)
        (folder/name).write_bytes(raw)
    old=folder/"gestionnaire-batocera-v4.1.4-TEST.sh"
    new=folder/"gestionnaire-batocera-v5.0.sh"
    helper=folder/"quiver-v416.py"
    source=old.read_bytes()
    oldhash="8a86f5d95e02e3da8bb8515f88014e758139e91af7deb9581a63ac9cd6afbf84"
    require(hashlib.sha256(source).hexdigest()==oldhash,"Source v4.1.4 non conforme")
    module=ast.parse(helper.read_text(encoding="utf-8"))
    code=next(ast.literal_eval(n.value) for n in module.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=="BASH" for t in n.targets))
    s=source.decode("utf-8")
    anchor="v41_apps(){ v41_menu 'APPLICATIONS'"
    s=replace_once(s,anchor,code+"\n"+anchor)
    s=replace_once(s,"'Syncthing' syncthing_menu -; }","'Syncthing' syncthing_menu - 'Quiver' v416_quiver -; }")
    s=s.replace("v4.1.4 TEST","v5.0")
    import runpy
    ui=runpy.run_path(str(folder/"interface-v500.py"))
    s=ui["patch_manager"](s)
    subprocess.run(["bash","-n"],input=ui["LAUNCHER"].encode("utf-8"),check=True)
    geo=ui["LAUNCHER"].split("<<'PYGEO'\n",1)[1].split("\nPYGEO",1)[0]
    compile(geo,"PYGEO","exec")
    new.write_bytes(s.encode("utf-8"))
    subprocess.run(["bash","-n",str(new)],check=True)
    compile(helper.read_bytes(),str(helper),"exec")
    installer=(folder/"install-v4.1.4.sh").read_text(encoding="utf-8")
    installer=installer.replace("v4.1.4","v5.0").replace("v5.0-TEST.sh","v5.0.sh").replace("v5.0 TEST","v5.0").replace("v414","v416")
    installer=installer.replace(oldhash,hashlib.sha256(new.read_bytes()).hexdigest())
    needle="correctif-sinden-boutons-reels-batocera44.sh; do"
    require(installer.count(needle)==3,"Liste de modules inattendue")
    installer=installer.replace(needle,"correctif-sinden-boutons-reels-batocera44.sh quiver-v416.py interface-v500.py; do")
    h=hashlib.sha256(helper.read_bytes()).hexdigest()
    ui_hash=hashlib.sha256((folder/"interface-v500.py").read_bytes()).hexdigest()
    installer=replace_once(installer,"\nSHA256BLONDINV4\n","\n"+h+"  quiver-v416.py\n"+ui_hash+"  interface-v500.py\nSHA256BLONDINV4\n")
    installer=replace_once(installer,"# Toutes les validations se font avant toute modification des chemins persistants.",
        "python3 -m py_compile \"$SRC_DIR/quiver-v416.py\" \"$SRC_DIR/interface-v500.py\"\n# Toutes les validations se font avant toute modification des chemins persistants.")
    installer=replace_once(installer,"ordre des systèmes arcade et classement par constructeur/date, Syncthing et 1fichier.","ordre des systèmes arcade et classement par constructeur/date, Syncthing, Quiver et 1fichier.")
    # Do not overwrite the Ports gamelist while ES is active.
    anchor="try:\n    tree=ET.parse(path)"
    guard="for proc in Path('/proc').glob('[0-9]*/comm'):\n    try:\n        active=proc.read_text().strip().startswith('emulationstatio')\n    except OSError:\n        continue\n    if active:\n        print('[INFO] ES actif : fiche Ports conservee ; actualiser les jeux apres installation.')\n        sys.exit(0)\ntry:\n    tree=ET.parse(path)"
    installer=replace_once(installer,anchor,guard)
    installer=ui["patch_installer"](installer)
    # Embedded installer is always invoked in local mode.
    out=folder/"install-v5.0.sh"
    out.write_text(installer,encoding="utf-8")
    subprocess.run(["bash","-n",str(out)],check=True)
    for p in folder.glob("correctif-sinden*.sh"):
        subprocess.run(["sh","-n",str(p)],check=True)
    for p in folder.glob("installer-sinden*.sh"):
        subprocess.run(["sh","-n",str(p)],check=True)
    compile((folder/"ordre-systemes-v4.py").read_bytes(),"ordre-systemes-v4.py","exec")
    print("[OK] Integrite des 9 fichiers et syntaxe des modules verifiees.")
    return out

def main():
    require(len(sys.argv)<=2 and (len(sys.argv)==1 or sys.argv[1]=="--check"),"Usage : python3 install-gestionnaire-v5.0-COMPLET.py [--check]")
    check=len(sys.argv)==2
    if not check:
        require(os.geteuid()==0,"Connexion root requise")
        osrel=Path("/etc/os-release").read_text()
        require("batocera" in osrel.lower() and re.search(r"\b44\b",osrel),"Batocera 44 requis")
    with tempfile.TemporaryDirectory(prefix="blondin-v500-complet-") as d:
        installer=build(Path(d))
        if check:
            print("[OK] Verification seule : aucun fichier persistant modifie.")
            return
        subprocess.run(["bash",str(installer)],check=True)
    print("[OK] Gestionnaire v5.0 complet installe, sans redemarrage automatique.")

if __name__=="__main__":
    try:
        main()
    except Exception as e:
        print("[ERREUR]",e,file=sys.stderr)
        sys.exit(1)
